import * as T from '../vendor/three.module.js';
import {loadHouse,daylight} from './model-loader.js?v=finishes6';
import {houses,lotExample,lotOffset} from '../house-data.js?v=finishes6';
import {createLotEnvironment} from './lot-environment.js?v=collection14';
const key=new URLSearchParams(location.search).get('house')==='bell'?'b':'a',home=houses[key],asset=p=>'../'+p;
document.title=home.name+' · Rainbow Park Collection';document.querySelector('#house-title').textContent=home.name;document.querySelector('#house-description').textContent=home.description;
document.querySelectorAll('.studio-models a').forEach(a=>a.setAttribute('aria-current',String(a.href.includes('house='+home.slug))));
document.querySelector('#metrics').innerHTML=`<div><b>${home.living.toLocaleString('en-US')} ft²</b><small>ÁREA HABITABLE</small></div><div><b>${home.total.toLocaleString('en-US')} ft²</b><small>TOTAL SEGÚN PLANO</small></div><div><b>${key==='a'?'3 + estudio':'3'}</b><small>DORMITORIOS</small></div><div><b>${key==='a'?3:2}</b><small>BAÑOS · 1 GARAJE</small></div>`;
const plan=document.querySelector('#floor');plan.src=asset(home.plan);plan.alt='Plano arquitectónico de '+home.name;document.querySelector('#plan-link').href=asset(home.pdf);document.querySelector('#model-link').href=asset(home.model);if(home.elevations){document.querySelector('#elevations-link').hidden=false;document.querySelector('#elevations-link').href=asset(home.elevations)}
const host=document.querySelector('#view'),status=document.querySelector('#status'),scene=new T.Scene();scene.background=new T.Color('#e8e8e1');const camera=new T.PerspectiveCamera(40,1,.04,300);let renderer,model,environment,mode=new URLSearchParams(location.search).get('view')||'exterior',drag,yaw=0,pitch=0;let orbit={az:.2,phi:1.36,d:29},target=new T.Vector3(0,1.5,0),eye=new T.Vector3();
const ground=new T.Mesh(new T.CircleGeometry(35,80),new T.MeshStandardMaterial({color:'#c4cbb7',roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.y=-.18;ground.receiveShadow=true;scene.add(ground);scene.add(new T.HemisphereLight(0xf5f6ff,0xaaa294,1.15));const sun=new T.DirectionalLight(0xfff1d6,2.4);sun.position.set(-14,25,20);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-24,right:24,top:24,bottom:-24,near:1,far:110});sun.shadow.normalBias=.008;sun.shadow.bias=-.00006;scene.add(sun);
const isInterior=()=>Boolean(home.camera[mode]);
function draw(){if(!renderer)return;camera.zoom=isInterior()?1:Math.min(1,camera.aspect/1.25);camera.fov=isInterior()?68:40;camera.updateProjectionMatrix();if(isInterior()){camera.position.copy(eye);camera.lookAt(eye.x+Math.sin(yaw)*Math.cos(pitch),eye.y+Math.sin(pitch),eye.z+Math.cos(yaw)*Math.cos(pitch))}else{const s=Math.sin(orbit.phi);camera.position.set(target.x+orbit.d*s*Math.sin(orbit.az),target.y+orbit.d*Math.cos(orbit.phi),target.z+orbit.d*s*Math.cos(orbit.az));camera.lookAt(target)}renderer.render(scene,camera)}
function switchView(next){mode=next;plan.hidden=next!=='plan';document.querySelector('.zoom').hidden=next==='plan';document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===next)));document.querySelectorAll('[data-room]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.room===next)));const lot=next==='lot';document.querySelector('#occupation').hidden=!lot;ground.visible=!lot;if(environment)environment.visible=lot;if(model){model.position.z=lot?lotOffset(home):0;model.children.filter(n=>n.userData.roof).forEach(n=>n.visible=next!=='cutaway')}
 target.set(0,1.5,0);if(next==='exterior')orbit={az:.2,phi:1.36,d:29};if(next==='cutaway')orbit={az:.05,phi:.12,d:26};if(lot){if(!environment){environment=createLotEnvironment();environment.scale.set(lotExample.width/23,1,lotExample.depth/44);environment.userData.setGarageSide?.(home.garageSide);scene.add(environment)}environment.visible=true;orbit={az:.25,phi:.62,d:67};target.set(0,0,0);document.querySelector('#occupation').innerHTML=`<b>Tu casa sobre un lote de referencia</b><br>MLS: 0.24 acres · 10,454 ft²<br>Dimensiones aproximadas: 76 × 135 pies<br>Fachada hacia la calle · lado corto<br>Base modelada: ${home.footprint.toFixed(2)} m²<br>Superficie fuera de la base: ${(lotExample.width*lotExample.depth-home.footprint).toFixed(1)} m²<small>Simulación sobre 76 × 135 pies (953.2 m²). El área MLS es 971.2 m²; se conservan ambas referencias hasta confirmar medidas. Implantación con 6 m frontales ilustrativos; la base de Utah incluye sus accesos exteriores.</small>`}
 if(isInterior()){const station=home.camera[next];eye.fromArray(station.position);const delta=new T.Vector3(...station.target).sub(eye).normalize();yaw=Math.atan2(delta.x,delta.z);pitch=Math.asin(delta.y)}status.textContent=next==='plan'?'Plano arquitectónico del cliente · Consulta el PDF para ampliar':lot?'Fachada al lado corto · Espacio posterior · Implantación ilustrativa':isInterior()?home.camera[next].label+' · Arrastra para mirar · Acabados propuestos':next==='cutaway'?'Distribución 3D según planos · Cubierta retirada':home.name+' · Arrastra para girar · Acabados propuestos';draw()}
for(const [id,station]of Object.entries(home.camera)){const b=document.createElement('button');b.dataset.room=id;b.textContent=station.label+' ↗';b.setAttribute('aria-pressed','false');b.onclick=()=>switchView(id);document.querySelector('#rooms').append(b)}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));
try{renderer=new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;host.prepend(renderer.domElement);daylight(scene,renderer);const canvas=renderer.domElement;canvas.tabIndex=0;canvas.setAttribute('aria-label','Modelo de '+home.name+'. Arrastra o usa flechas para girar.');const size=()=>{renderer.setSize(host.clientWidth,host.clientHeight,false);camera.aspect=host.clientWidth/host.clientHeight;draw()};new ResizeObserver(size).observe(host);size();
 canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,...orbit,yaw,pitch};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;if(isInterior()){yaw=drag.yaw-(e.clientX-drag.x)*.004;pitch=T.MathUtils.clamp(drag.pitch+(e.clientY-drag.y)*.004,-1.2,1.2)}else{orbit.az=drag.az-(e.clientX-drag.x)*.006;orbit.phi=T.MathUtils.clamp(drag.phi+(e.clientY-drag.y)*.004,.02,1.5)}draw()};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;
 function zoom(f){if(isInterior())return;orbit.d=T.MathUtils.clamp(orbit.d*f,12,100);draw()}
 document.querySelector('#zoom-in').onclick=()=>zoom(.85);document.querySelector('#zoom-out').onclick=()=>zoom(1.18);document.querySelector('#reset').onclick=()=>switchView(isInterior()?'exterior':mode);
 canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','Escape'].includes(e.key))return;e.preventDefault();if(e.key==='Escape')return switchView('exterior');if(['+','=','-'].includes(e.key))return zoom(e.key==='-'?1.18:.85);const x=e.key==='ArrowLeft'?-.1:e.key==='ArrowRight'?.1:0,y=e.key==='ArrowUp'?-.1:e.key==='ArrowDown'?.1:0;if(isInterior()){yaw+=x;pitch=T.MathUtils.clamp(pitch-y,-1.2,1.2)}else{orbit.az+=x;orbit.phi=T.MathUtils.clamp(orbit.phi+y,.02,1.5)}draw()});
 loadHouse(asset(home.model)).then(m=>{model=m;scene.add(model);switchView(mode)}).catch(()=>{status.textContent='El modelo no pudo cargarse. Puedes consultar el plano original.';switchView('plan')});
 document.querySelector('#save-view').onclick=()=>{const a=document.createElement('a');a.href=mode==='plan'?plan.src:renderer.domElement.toDataURL('image/png');a.download=home.slug+'-'+mode+'.png';a.click()};
}catch{status.textContent='Vista 3D no disponible en este dispositivo. Consulta el plano arquitectónico.';plan.hidden=false;document.querySelector('.zoom').hidden=true}
